command:
// Öffnet das Wildnisreise-Fenster.
//
// Das Fenster ist für alle da: Spieler sehen denselben Reisetag, dasselbe
// Wetter und denselben Tagesbericht, können aber nur ihre eigenen Charaktere
// in eine Rolle eintragen und für sie würfeln. Es ist also unbedenklich,
// dieses Makro auf die gemeinsame Hotbar zu legen.
const api = game.modules.get("toa-adventure-tracker")?.api;

if (!api) {
  ui.notifications.error("Das Modul 'Wildnisreise' ist nicht aktiv.");
} else {
  api.open();
}

// Ablauf eines Reisetags:
